/**
 * @file test/scale/source-cli-environment.test.ts
 * @description The explicit environment of the Bun source CLI child (`test/scale/source-cli.ts`).
 *
 * The child gets an allowlist of the already-sanitized test environment, never the whole parent
 * environment. Every child guard bootstrap setting must survive that allowlist, including the runtime
 * declaration: without it a further child generated by the source CLI would fall back to Node-only
 * coverage. A configured guard that does not declare Bun coverage must stop the launch, an ambient
 * credential must not pass, and the provider settings are blanked. Only the constructed environment
 * is checked; no process is started.
 */

import path from "node:path";
import { describe, expect, it } from "bun:test";
import { afterEach } from "../config/storage-profile-hooks.js";
import { restoreEnv, stubEnv } from "../stubs.js";
import { CHILD_GUARD_ENV, preloadFlag } from "../fixtures/child-guard-bootstrap.js";
import { guardRoots } from "../fixtures/guard-root.js";
import { SOURCE_CLI_ALLOWED_ENV, sourceCliEnvironment } from "./source-cli.js";

const roots = guardRoots("llmwiki-source-cli-env-", "guard-entry.mjs");

afterEach(async () => {
  restoreEnv();
  await roots.cleanup();
});

/** Configure the child guard bootstrap with a real guard module in a fresh root, declaring `runtimes`. */
async function configureGuard(runtimes: string): Promise<{ url: string; log: string }> {
  const { root, url, log } = await roots.create();
  const config = { url, log };
  stubEnv(CHILD_GUARD_ENV.url, config.url);
  stubEnv(CHILD_GUARD_ENV.log, config.log);
  stubEnv(CHILD_GUARD_ENV.denyExec, process.execPath);
  stubEnv(CHILD_GUARD_ENV.census, path.join(root, "census.jsonl"));
  stubEnv(CHILD_GUARD_ENV.runtimes, runtimes);
  return config;
}

describe("the source CLI child environment", () => {
  it("keeps every child guard setting, the runtime declaration included, and no ambient credential", async () => {
    const config = await configureGuard("node,bun");
    stubEnv("BUN_OPTIONS", undefined);
    stubEnv("OPENAI_API_KEY", "sk-ambient-must-not-pass");
    const env = sourceCliEnvironment();
    expect(env[CHILD_GUARD_ENV.runtimes]).toBe("node,bun");
    expect([env[CHILD_GUARD_ENV.url], env[CHILD_GUARD_ENV.log], env[CHILD_GUARD_ENV.denyExec]]).toEqual([config.url, config.log, process.execPath]);
    expect(env.BUN_OPTIONS).toBe(preloadFlag("bun", config.url));
    expect(env.OPENAI_API_KEY).toBeUndefined();
    expect([env.ANTHROPIC_API_KEY, env.ANTHROPIC_AUTH_TOKEN]).toEqual(["", ""]);
  });

  it("refuses to build the environment when the configured guard does not declare Bun coverage", async () => {
    await configureGuard("node");
    expect(() => sourceCliEnvironment()).toThrow(/does not cover bun children/);
  });

  it("allowlists every child guard bootstrap setting by its own name", () => {
    for (const name of Object.values(CHILD_GUARD_ENV)) expect(SOURCE_CLI_ALLOWED_ENV).toContain(name);
  });
});
